const raw = $input.first().json;
const geo = typeof raw.data === 'string' ? JSON.parse(raw.data) : raw;
const feat = geo.features[0];
const ring = feat.geometry.coordinates[0];
const cfg = $('Set Configuration').first().json;
const inside = (x, y) => { let c = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i], [xj, yj] = ring[j];
    if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) c = !c;
  } return c; };
const xs = ring.map(p => p[0]), ys = ring.map(p => p[1]);
const [minX, maxX, minY, maxY] = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
const n = cfg.gridSteps, pts = [{ json: { lat: cfg.lat, lng: cfg.lng } }];
for (let i = 0; i <= n; i++) for (let j = 0; j <= n; j++) {
  const x = minX + (maxX - minX) * i / n, y = minY + (maxY - minY) * j / n;
  if (inside(x, y)) pts.push({ json: { lat: y, lng: x } });
}
return pts;

const cfg = $('Set Configuration').first().json;
const zips = [...new Set($input.all()
  .map(i => (i.json.address || {}).postcode)
  .filter(Boolean).map(z => String(z).slice(0, 5)))].slice(0, cfg.maxZips);
if (!zips.length) throw new Error('No ZIP codes found inside the drive-time polygon.');
return zips.map(z => ({ json: { zip: z } }));

const cfg = $('Set Configuration').first().json;
const geos = [], names = [];
for (const it of $input.all()) {
  const s = (it.json.geoTargetConstantSuggestions || []).find(x =>
    x.geoTargetConstant && x.geoTargetConstant.targetType === 'Postal Code' && x.geoTargetConstant.countryCode === 'US');
  if (s) { geos.push(s.geoTargetConstant.resourceName); names.push(s.geoTargetConstant.canonicalName); }
}
if (!geos.length) throw new Error('No Google Ads geo target constants matched the ZIP codes.');
const keywords = [...new Set(cfg.categories.flatMap(c => c.keywords))];
return [{ json: { geos: [...new Set(geos)], zipsMatched: [...new Set(names)], keywords } }];

const cfg = $('Set Configuration').first().json;
const geo = $('Build Geo Target Set').first().json;
const polyRaw = $('Get Drive-Time Polygon').first().json;
const polyGeo = typeof polyRaw.data === 'string' ? JSON.parse(polyRaw.data) : polyRaw;
const ring = polyGeo.features[0].geometry.coordinates[0];
const results = $input.first().json.results || [];
const m = {};
for (const r of results) {
  const k = r.keywordMetrics || {};
  m[(r.text || '').toLowerCase()] = { vol: Number(k.avgMonthlySearches || 0),
    bidLow: Number(k.lowTopOfPageBidMicros || 0) / 1e6, bidHigh: Number(k.highTopOfPageBidMicros || 0) / 1e6 };
}
const cats = cfg.categories.map(c => {
  const kws = c.keywords.map(k => ({ keyword: k, ...(m[k.toLowerCase()] || { vol: 0, bidLow: 0, bidHigh: 0 }) }));
  const vol = kws.reduce((a, k) => a + k.vol, 0);
  const cpc = vol ? kws.reduce((a, k) => a + k.vol * (k.bidLow + k.bidHigh) / 2, 0) / vol : 0;
  const scenarios = {};
  for (const t of ['low', 'high']) {
    const p = c.tiers[t];
    const impressions = vol * cfg.impressionShare, clicks = impressions * p.ctr;
    const lpv = clicks * p.lpViewRate, actions = lpv * p.actionRate, customers = actions * c.closeRate;
    const spend = clicks * cpc, revenue = customers * p.price * c.billableUnits;
    scenarios[t] = { price: p.price, volume: vol, impressions, ctr: p.ctr, clicks, lpv, actionRate: p.actionRate,
      actions, customers, spend, cpa: customers ? spend / customers : null, revenue };
  }
  return { ...c, kws, vol, cpc, scenarios };
});
const step = Math.ceil(ring.length / 60);
const coords = ring.filter((_, i) => i % step === 0).map(p => p[0].toFixed(5) + ',' + p[1].toFixed(5)).join(',');
const mapUrl = 'https://maps.geoapify.com/v1/staticmap?style=osm-bright&width=900&height=600&scaleFactor=2'
  + '&geometry=polygon:' + coords + ';linecolor:%23d32f2f;linewidth:3;fillcolor:%23d32f2f33'
  + '&marker=lonlat:' + cfg.lng + ',' + cfg.lat + ';color:%231a73e8;size:large';
return [{ json: { cfg: { locationLabel: cfg.locationLabel, driveMinutes: cfg.driveMinutes, impressionShare: cfg.impressionShare }, zips: geo.zipsMatched, cats, mapUrl } }];

const d = $('Calculate Funnel Model').first().json;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mapB64 = buf.toString('base64');
const f = n => n == null ? 'n/a' : (n >= 100 ? Math.round(n).toLocaleString('en-US') : n.toFixed(1));
const usd = n => n == null ? 'n/a' : '$' + Math.round(n).toLocaleString('en-US');
const funnel = (title, stages, color) => {
  const W = 420, max = Math.max(stages[0].v, 1);
  let y = 30, o = `<svg viewBox="0 0 ${W} ${stages.length * 52 + 34}" width="100%" xmlns="http://www.w3.org/2000/svg" font-family="Helvetica,Arial">`
    + `<text x="210" y="18" text-anchor="middle" font-size="13" font-weight="bold">${title}</text>`;
  for (const s of stages) {
    const w = Math.max(70, 380 * Math.log10(s.v + 1) / Math.log10(max + 1)), x = (W - w) / 2;
    o += `<rect x="${x}" y="${y}" width="${w}" height="40" rx="4" fill="${color}"/>`
      + `<text x="210" y="${y + 16}" text-anchor="middle" fill="#fff" font-size="11">${s.l}</text>`
      + `<text x="210" y="${y + 33}" text-anchor="middle" fill="#fff" font-size="14" font-weight="bold">${f(s.v)}</text>`;
    y += 52;
  }
  return o + '</svg>';
};
const stages = s => [
  { l: 'Monthly search volume', v: s.volume }, { l: 'Impressions', v: s.impressions },
  { l: `Clicks (CTR ${(s.ctr * 100).toFixed(1)}%)`, v: s.clicks }, { l: 'Landing page views', v: s.lpv },
  { l: `Actions (rate ${(s.actionRate * 100).toFixed(1)}%)`, v: s.actions }, { l: 'Estimated customers', v: s.customers } ];
let html = `<html><head><meta charset="utf-8"><style>
body{font-family:Helvetica,Arial;color:#222;font-size:12px} h1{font-size:22px} h2{font-size:17px;border-bottom:2px solid #1a73e8;padding-bottom:4px}
.row{display:flex;gap:12px} .row>div{flex:1} table{border-collapse:collapse;width:100%;margin:8px 0} td,th{border:1px solid #ccc;padding:4px 6px;text-align:right}
td:first-child,th:first-child{text-align:left} th{background:#f1f3f4} .pb{page-break-before:always} .note{color:#666;font-size:10px}</style></head><body>
<h1>Search Demand &amp; Conversion Funnel Model</h1>
<p><b>Location:</b> ${d.cfg.locationLabel}<br><b>Trade area:</b> ~${d.cfg.driveMinutes}-minute drive polygon, targeted via ${d.zips.length} ZIP codes<br>
<b>Generated:</b> ${new Date().toISOString().slice(0, 10)}</p>
<img src="data:image/png;base64,${mapB64}" style="width:100%"/>
<p class="note">Red outline: drive-time polygon. Targeted Keyword Planner locations: ${d.zips.join('; ')}</p>`;
for (const c of d.cats) {
  html += `<div class="pb"><h2>${c.name}</h2>
  <table><tr><th>Keyword</th><th>Avg monthly searches</th><th>Top-of-page bid (low-high)</th></tr>
  ${c.kws.map(k => `<tr><td>${k.keyword}</td><td>${f(k.vol)}</td><td>$${k.bidLow.toFixed(2)} - $${k.bidHigh.toFixed(2)}</td></tr>`).join('')}</table>
  <div class="row"><div>${funnel('LOW price: $' + c.scenarios.low.price + ' / ' + c.unitLabel, stages(c.scenarios.low), '#1a73e8')}</div>
  <div>${funnel('HIGH price: $' + c.scenarios.high.price + ' / ' + c.unitLabel, stages(c.scenarios.high), '#e8710a')}</div></div>
  <p class="note">Bar widths use a log scale. Funnel steps are scenario assumptions; only search volume and bids come from Keyword Planner.</p>
  <table><tr><th>Metric</th><th>Low price</th><th>High price</th></tr>
  <tr><td>Est. monthly customers</td><td>${f(c.scenarios.low.customers)}</td><td>${f(c.scenarios.high.customers)}</td></tr>
  <tr><td>Est. monthly ad spend (avg CPC $${c.cpc.toFixed(2)})</td><td>${usd(c.scenarios.low.spend)}</td><td>${usd(c.scenarios.high.spend)}</td></tr>
  <tr><td>Cost per customer</td><td>${usd(c.scenarios.low.cpa)}</td><td>${usd(c.scenarios.high.cpa)}</td></tr>
  <tr><td>Est. first-period revenue</td><td>${usd(c.scenarios.low.revenue)}</td><td>${usd(c.scenarios.high.revenue)}</td></tr></table></div>`;
}
html += '</body></html>';
return [{ json: { html } }];
